#[path="recovery_observer_environment_tests.rs"]mod environment;
#[path="recovery_observer_lifetime_tests.rs"]mod lifetime;
#[path="recovery_observer_safety_tests.rs"]mod safety;
#[path="recovery_observer_loopback_tests.rs"]mod loopback;
use super::*;
use std::sync::{Mutex,atomic::AtomicUsize};
use bytes::Bytes;
use webrtc::{interceptor::{chain::Chain,mock::mock_stream::MockStream,stream_info::RTCPFeedback},rtp::{packet::Packet,header::Header},rtcp::transport_feedbacks::transport_layer_nack::NackPair};

#[derive(Default)]struct Sink{packets:Mutex<Vec<(Packet,Attributes)>>,error:AtomicBool}
#[async_trait]impl RTPWriter for Sink{async fn write(&self,p:&Packet,a:&Attributes)->Result<usize,webrtc::interceptor::Error>{self.packets.lock().unwrap().push((p.clone(),a.clone()));if self.error.load(Ordering::Relaxed){Err(webrtc::interceptor::Error::Other("sentinel-write-error".into()))}else{Ok(777)}}}
fn packet()->Packet{Packet{header:Header{version:2,ssrc:42,payload_type:98,sequence_number:65535,timestamp:90000,marker:true,..Default::default()},payload:Bytes::from_static(b"synthetic-video-untouched")}}
fn observer(tap:Tap)->Observer{Observer{tap,epoch:AtomicU64::new(1),streams:Mutex::new(Vec::new())}}
fn info()->StreamInfo{StreamInfo{ssrc:42,payload_type:98,mime_type:"video/H264".into(),clock_rate:90000,rtcp_feedback:vec![RTCPFeedback{typ:"nack".into(),parameter:String::new()}],..Default::default()}}
#[tokio::test]async fn rtp_data_and_attributes_unchanged(){let(t,rx)=Tap::memory(8);let o=observer(t);let sink=Arc::new(Sink::default());let writer=o.bind_local_stream(&info(),sink.clone()).await;let mut a=Attributes::new();a.insert(9,17);let p=packet();assert_eq!(writer.write(&p,&a).await.unwrap(),777);assert_eq!(sink.packets.lock().unwrap()[0],(p,a));let rows:Vec<_>=rx.try_iter().collect();assert!(rows.iter().any(|e|matches!(e.data,Data::Rtp{ssrc:42,seq:65535,pt:98,returned_bytes:777,ok:true,..})));}
#[tokio::test]async fn rtp_error_not_hidden(){let(t,rx)=Tap::memory(8);let o=observer(t);let sink=Arc::new(Sink::default());sink.error.store(true,Ordering::Relaxed);let writer=o.bind_local_stream(&info(),sink).await;let err=writer.write(&packet(),&Attributes::new()).await.unwrap_err();assert!(err.to_string().contains("sentinel-write-error"));assert!(rx.try_iter().any(|e|matches!(e.data,Data::Rtp{ok:false,..})));}
#[tokio::test]async fn full_observation_queue_still_sends(){let(t,_rx)=Tap::memory(1);let o=observer(t);let sink=Arc::new(Sink::default());let writer=o.bind_local_stream(&info(),sink.clone()).await;for _ in 0..1000{assert_eq!(writer.write(&packet(),&Attributes::new()).await.unwrap(),777);}assert_eq!(sink.packets.lock().unwrap().len(),1000);}
#[tokio::test]async fn close_and_unbind_do_not_touch_media(){let(t,rx)=Tap::memory(10);let o=observer(t);let sink=Arc::new(Sink::default());let writer=o.bind_local_stream(&info(),sink.clone()).await;o.unbind_local_stream(&info()).await;writer.write(&packet(),&Attributes::new()).await.unwrap();o.close().await.unwrap();writer.write(&packet(),&Attributes::new()).await.unwrap();assert_eq!(sink.packets.lock().unwrap().len(),2);assert!(!rx.try_iter().any(|e|matches!(e.data,Data::Rtp{..})));}
#[tokio::test]async fn rebinding_ssrc_disables_old_observer_epoch(){let(t,rx)=Tap::memory(16);let o=observer(t);let sink=Arc::new(Sink::default());let old=o.bind_local_stream(&info(),sink.clone()).await;let new=o.bind_local_stream(&info(),sink.clone()).await;old.write(&packet(),&Attributes::new()).await.unwrap();new.write(&packet(),&Attributes::new()).await.unwrap();let rows:Vec<_>=rx.try_iter().filter(|e|matches!(e.data,Data::Rtp{..})).collect();assert_eq!(rows.len(),1);assert!(matches!(rows[0].data,Data::Rtp{epoch:2,..}));}
struct ReadOnce{packets:Mutex<Option<Vec<Box<dyn RtcpPacket+Send+Sync>>>>,calls:AtomicUsize}
#[async_trait]impl RTCPReader for ReadOnce{async fn read(&self,b:&mut[u8],_:&Attributes)->Result<(Vec<Box<dyn RtcpPacket+Send+Sync>>,Attributes),webrtc::interceptor::Error>{self.calls.fetch_add(1,Ordering::Relaxed);b[0]=99;match self.packets.lock().unwrap().take(){Some(p)=>Ok((p,Attributes::from([(8,9)]))),None=>Err(webrtc::interceptor::Error::Other("sentinel-read-error".into()))}}}
#[tokio::test]async fn rtcp_reader_preserves_packets_attributes_and_error(){let(t,rx)=Tap::memory(16);let input=Arc::new(ReadOnce{packets:Mutex::new(Some(vec![Box::new(TransportLayerNack{sender_ssrc:1,media_ssrc:42,nacks:vec![NackPair{packet_id:65535,lost_packets:3}]}),Box::new(ReceiverReport{ssrc:1,reports:vec![webrtc::rtcp::reception_report::ReceptionReport{ssrc:42,fraction_lost:5,last_sequence_number:65538,last_sender_report:123,delay:32768,..Default::default()}],..Default::default()})])),calls:AtomicUsize::new(0)});let reader=RtcpIn{inner:input.clone(),tap:t};let mut b=[0;1500];let(p,a)=reader.read(&mut b,&Attributes::new()).await.unwrap();assert_eq!(p.len(),2);assert_eq!(a.get(&8),Some(&9));assert_eq!(b[0],99);assert_eq!(p[0].as_any().downcast_ref::<TransportLayerNack>().unwrap().nacks[0].lost_packets,3);let rows:Vec<_>=rx.try_iter().collect();assert!(rows.iter().any(|e|matches!(e.data,Data::Nack{pid:65535,blp:3,..})));assert!(rows.iter().any(|e|matches!(e.data,Data::Rr{highest_sequence:65538,..})));assert!(reader.read(&mut b,&Attributes::new()).await.unwrap_err().to_string().contains("sentinel-read-error"));assert_eq!(input.calls.load(Ordering::Relaxed),2);}
#[tokio::test]async fn real_sdk_nack_responder_retransmit_is_observed_unchanged(){
 let(t,rx)=Tap::memory(128);let obs=Arc::new(observer(t));let responder=webrtc::interceptor::nack::responder::Responder::builder().with_log2_size(5).build("").unwrap();let chain=Arc::new(Chain::new(vec![obs,responder]));let stream=MockStream::new(&info(),chain).await;
 for seq in [10,11,12]{let mut p=packet();p.header.sequence_number=seq;stream.write_rtp(&p).await.unwrap();let actual=tokio::time::timeout(std::time::Duration::from_secs(1),stream.written_rtp()).await.unwrap().unwrap();assert_eq!(actual,p);}
 stream.receive_rtcp(vec![Box::new(TransportLayerNack{sender_ssrc:1,media_ssrc:42,nacks:vec![NackPair{packet_id:11,lost_packets:0}]})]).await;
 let resend=tokio::time::timeout(std::time::Duration::from_secs(1),stream.written_rtp()).await.unwrap().unwrap();assert_eq!(resend.header.sequence_number,11);assert_eq!(resend.payload,packet().payload);stream.close().await.unwrap();
 let rows:Vec<_>=rx.try_iter().collect();assert_eq!(rows.iter().filter(|e|matches!(e.data,Data::Rtp{seq:11,..})).count(),2);assert!(rows.iter().any(|e|matches!(e.data,Data::Nack{pid:11,..})));
}
#[tokio::test]async fn real_sdk_sender_reports_reach_innermost_writer(){
 let(t,rx)=Tap::memory(128);let obs=Arc::new(observer(t));let reports=webrtc::interceptor::report::sender::SenderReport::builder().with_interval(std::time::Duration::from_millis(20)).build("").unwrap();let stream=MockStream::new(&info(),Arc::new(Chain::new(vec![obs,reports]))).await;stream.write_rtp(&packet()).await.unwrap();let _=stream.written_rtp().await;
 let pkts=tokio::time::timeout(std::time::Duration::from_secs(2),stream.written_rtcp()).await.unwrap().unwrap();let sr=pkts[0].as_any().downcast_ref::<SenderReport>().unwrap();let ntp=sr.ntp_time;let timestamp=sr.rtp_time;stream.close().await.unwrap();assert!(rx.try_iter().any(|e|matches!(e.data,Data::Sr{ssrc:42,compact_ntp:n,rtp,ok:true,..}if n==(ntp>>16)as u32&&rtp==timestamp)));
}
